/**
 * The public `RateLimiter`: a thin TypeScript class over the native one.
 *
 * Why wrap it? Returning an object from Rust costs one call into V8 per field,
 * which made `check()` about 10x slower than `allow()`. Here the native
 * `checkInto()` writes plain numbers into a reused `Float64Array` and the
 * object is built in JavaScript, where V8 creates it almost for free.
 */

// Namespace import: works the same in CommonJS and ESM when consuming the
// native addon (a CJS module generated by napi-rs).
import * as native from "../binding.js";
import type {
  CheckResult,
  RateLimitStats,
  RateLimiterOptions,
} from "../binding.js";

/**
 * Scratch buffer for `checkInto`. One per module is enough: JavaScript runs
 * one call at a time per thread, the native call is synchronous and never
 * calls back into JS, and each worker thread loads its own copy.
 */
const out = new Float64Array(7);

/**
 * Local (in-process) rate limiter with Fixed Window and Sliding Window
 * algorithms and a Rust core.
 *
 * ```ts
 * import { RateLimiter } from "rust-node-rate-limit";
 *
 * const limiter = new RateLimiter({ limit: 100, windowSeconds: 60 });
 * limiter.allow("user:123");      // true / false
 * limiter.check("user:123");      // { allowed, limit, remaining, retryAfter, resetAfter, ... }
 * ```
 */
export class RateLimiter {
  private readonly native: native.RateLimiter;

  /** @throws if `limit`, `windowSeconds` or `algorithm` is invalid. */
  constructor(options: RateLimiterOptions) {
    this.native = new native.RateLimiter(options);
  }

  /** The active algorithm: `"fixed"` or `"sliding"`. */
  get algorithm(): string {
    return this.native.algorithm;
  }

  /** Tries to consume one request for `key`. Returns `true` if allowed. */
  allow(key: string): boolean {
    return this.native.allow(key);
  }

  /** Like `allow()`, but returns the detailed result of the check. */
  check(key: string): CheckResult {
    this.native.checkInto(key, out);
    return {
      allowed: out[0] === 1,
      limit: out[1],
      remaining: out[2],
      retryAfter: out[3],
      resetAfter: out[4],
      retryAfterMs: out[5],
      resetAfterMs: out[6],
    };
  }

  /**
   * Requests left for `key` in the current window (read-only: does not
   * consume). If the key does not exist or its window expired, returns the limit.
   */
  remaining(key: string): number {
    return this.native.remaining(key);
  }

  /** Removes the state of a single key (resets its count). */
  reset(key: string): void {
    this.native.reset(key);
  }

  /** Removes the state of every key. Does not reset the `stats()` counters. */
  clear(): void {
    this.native.clear();
  }

  /** Removes keys whose window expired and returns how many were removed. */
  cleanup(): number {
    return this.native.cleanup();
  }

  /** Returns the accumulated counters and the number of active keys. */
  stats(): RateLimitStats {
    return this.native.stats();
  }
}
